{{ get_solua_print_css() }}{% set p = get_wholesale_print_data(doc) %}{% set company = p.company %}{% set customer = p.customer %}{% set show_item_name = doc.get('custom_print_item_name') if doc.get('custom_print_item_name') is not none else 1 %}{% set print_show_spu = frappe.form_dict.get('show_spu') %}{% set show_spu = (print_show_spu == '1') if print_show_spu is not none else (doc.get('custom_print_spu') if doc.get('custom_print_spu') is not none else 0) %}{% set show_sku = doc.get('custom_print_sku') if doc.get('custom_print_sku') is not none else 1 %}{% set show_color_code = doc.get('custom_print_color_code') if doc.get('custom_print_color_code') is not none else 1 %}{% set show_description = doc.get('custom_print_description') if doc.get('custom_print_description') is not none else 1 %}{% set show_images = 1 if doc.get('custom_print_color_images') else 0 %}
<div class="company-header">{% if company.logo %}<img class="company-logo" src="{{ company.logo | e }}" alt="Solua Home">{% endif %}<h2>Confirmação de Encomenda / 订单确认单</h2></div>
{% if doc.docstatus != 1 %}<div class="warning">{{ 'RASCUNHO / 草稿' if doc.docstatus == 0 else 'CANCELADO / 已取消' }} — 非正式凭证</div>{% endif %}
{% if p.get('legacy') %}<div class="warning">历史单据未保存打印快照，所示补充主资料为当前资料。</div>{% endif %}
<table class="meta"><tr><td><b>{{ company.name | e }}</b><br>NUIT: {{ company.nuit | e }}<br>{{ company.address }}<br>Tel: {{ company.phone | e }}</td><td><b>Cliente / 客户: {{ customer.name | e }}</b><br>NUIT: {{ customer.nuit or 'Não informado / 未提供' | e }}<br>Loja / 门店: {{ customer.store | e }}<br>{{ customer.address }}<br>{{ customer.contact }} · {{ customer.phone | e }}</td></tr><tr><td>N.º / 编号: {{ doc.name | e }}<br>客户订单号: {{ doc.get('custom_customer_order_no') or '—' | e }}</td><td>Data / 日期: {{ doc.get('posting_date') or doc.get('transaction_date') }}<br>交期: {{ doc.get('delivery_date') or '—' }}</td></tr></table>
{% set so_dynamic = namespace(qty_chars=1, rate_chars=1) %}{% for so_item in p['items'] %}{% set so_qty_text = format_print_qty(so_item.qty) %}{% set so_rate_text = format_print_money(so_item.rate, currency=doc.currency, precision=0) %}{% if so_qty_text|length > so_dynamic.qty_chars %}{% set so_dynamic.qty_chars = so_qty_text|length %}{% endif %}{% if so_rate_text|length > so_dynamic.rate_chars %}{% set so_dynamic.rate_chars = so_rate_text|length %}{% endif %}{% endfor %}{% set so_qty_width = (so_dynamic.qty_chars + 1) * 100 %}{% set so_rate_width = (so_dynamic.rate_chars + 1) * 100 %}{% set so_width_total = 0 %}{% if show_item_name %}{% set so_width_total = so_width_total + 1464 %}{% endif %}{% if show_spu %}{% set so_width_total = so_width_total + 900 %}{% endif %}{% if show_sku %}{% set so_width_total = so_width_total + 1464 %}{% endif %}{% if show_color_code %}{% set so_width_total = so_width_total + 592 %}{% endif %}{% if show_images %}{% set so_width_total = so_width_total + 900 %}{% endif %}{% set so_width_total = so_width_total + 1800 %}{% if show_description %}{% set so_width_total = so_width_total + 2619 %}{% endif %}{% set so_width_total = so_width_total + so_qty_width + 403 + so_rate_width + 901 %}<table class="items"><colgroup>{% if show_images %}<col class="col-photo" style="width:{{ 100 * 900 / so_width_total }}%;">{% endif %}{% if show_item_name %}<col class="col-item" style="width:{{ 100 * 1464 / so_width_total }}%;">{% endif %}{% if show_spu %}<col class="col-spu" style="width:{{ 100 * 900 / so_width_total }}%;">{% endif %}{% if show_sku %}<col class="col-sku" style="width:{{ 100 * 1464 / so_width_total }}%;">{% endif %}{% if show_color_code %}<col class="col-color-code" style="width:{{ 100 * 592 / so_width_total }}%;">{% endif %}<col class="col-barcode" style="width:{{ 100 * 1800 / so_width_total }}%;">{% if show_description %}<col class="col-description" style="width:{{ 100 * 2619 / so_width_total }}%;">{% endif %}<col class="col-qty" style="width:{{ 100 * so_qty_width / so_width_total }}%;"><col class="col-uom" style="width:{{ 100 * 403 / so_width_total }}%;"><col class="col-rate" style="width:{{ 100 * so_rate_width / so_width_total }}%;"><col class="col-amount" style="width:{{ 100 * 901 / so_width_total }}%;"></colgroup><caption class="items-title">{{ doc.name | e }} · Encomenda / 订购</caption><thead><tr>{% if show_images %}<th class="col-photo">图</th>{% endif %}{% if show_item_name %}<th class="col-item">Artigo / 商品</th>{% endif %}{% if show_spu %}<th class="col-spu">SPU</th>{% endif %}{% if show_sku %}<th class="col-sku">SKU / 货号</th>{% endif %}{% if show_color_code %}<th class="col-color-code">Cor /<br>色号</th>{% endif %}<th class="col-barcode">EAN /<br>条码</th>{% if show_description %}<th class="col-description">Descrição /<br>描述</th>{% endif %}<th class="col-qty">Qt</th><th class="col-uom">Un.</th><th class="col-rate">Prc</th><th class="col-amount">Valor /<br>金额</th></tr></thead><tbody>
{% for item in p['items'] %}<tr>{% if show_images %}<td class="col-photo">{% if item.image %}<img class="photo" src="{{ item.image | e }}">{% endif %}</td>{% endif %}{% if show_item_name %}<td class="col-item">{{ item.item_name | e }}</td>{% endif %}{% if show_spu %}<td class="col-spu">{{ (item.spu_code or '—') | e }}</td>{% endif %}{% if show_sku %}<td class="col-sku">{% if p.get('customer_merged') %}{{ (item.order_code or item.item_code) | e }}{% else %}{{ item.item_code | e }}{% endif %}</td>{% endif %}{% if show_color_code %}<td class="col-color-code">{{ (item.color_code or '—') | e }}{% if item.color %}<br>{{ item.color | e }}{% endif %}</td>{% endif %}<td class="col-barcode">{{ (item.get('barcode') or '—') | e }}</td>{% if show_description %}<td class="col-description">{{ (item.get('description') or '—') | e }}</td>{% endif %}<td class='col-qty num'>{{ format_print_qty(item.qty) }}</td><td class="col-uom">{{ item.uom | e }}</td><td class="col-rate num">{{ format_print_money(item.rate, currency=doc.currency, precision=0) }}</td><td class="col-amount num">{{ format_print_money(item.amount, currency=doc.currency, precision=0) }}</td></tr>{% endfor %}
</tbody><tbody class="items-total"><tr><td colspan='{{ 1 + show_images + show_item_name + show_spu + show_sku + show_color_code + show_description }}' style='text-align:right'><b>Total Qty /<br>总数量</b></td><td style='text-align:right'><b>{{ get_print_total_qty(p) }}</b></td><td colspan='3'></td></tr></tbody></table><div class="block num">Total / 含税合计: {{ format_print_money(doc.grand_total, currency=doc.currency, precision=0) }}</div>
<div class="block">付款安排: {{ p.payment_method or '未维护' | e }} · 定金: {{ format_print_money(p.deposit, currency=doc.currency, precision=0) }} · 尾款到期: {{ p.balance_due_date or '—' | e }}<br>开票安排: {{ p.invoice_plan or '未维护' | e }}</div>
{% if doc.get('payment_schedule') %}<table><thead><tr><th>付款条件</th><th>到期日</th><th>金额</th></tr></thead><tbody>{% for row in doc.payment_schedule %}<tr><td>{{ row.payment_term or '' | e }}</td><td>{{ row.due_date }}</td><td>{{ format_print_money(row.payment_amount, currency=doc.currency, precision=0) }}</td></tr>{% endfor %}</tbody></table>{% endif %}
{% if doc.get('custom_print_color_qr') %}{% set seen = [] %}<div class="block">{% for item in p['items'] %}{% if item.template_code and item.template_code not in seen %}{% set unused = seen.append(item.template_code) %}{% set qr = get_color_card_qr_img(item.template_code) %}{% if qr %}<img class="qr" src="{{ qr | e }}">{{ item.template_code | e }} {% endif %}{% endif %}{% endfor %}</div>{% endif %}
<div id="footer-html" class="visible-pdf"><div class="text-center">{{ doc.name | e }} · <span class="page"></span> / <span class="topage"></span></div></div>

css:
@page{size:A4;margin:8mm 5mm}.print-format{font-size:var(--solua-font-size);color:#263238;padding:8mm 5mm !important;}h2{font-size:20px;color:#99732c}.print-format .company-header h2{color:#99732c}table{width:100%;border-collapse:collapse;table-layout:fixed;margin:10px 0}table.items{table-layout:fixed !important;width:100% !important}th,td{padding:var(--solua-cell-padding);border-bottom:1px solid #ddd;vertical-align:top;overflow-wrap:anywhere}th{background:#f5f1e9}thead{display:table-header-group}tr{page-break-inside:avoid}.meta td{width:50%}.num{text-align:right}.photo{max-width:45px;max-height:45px}.block{page-break-inside:avoid;margin-top:12px}.sign{height:95px;border:1px solid #bbb;padding:8px}.warning{color:#a35c00}.qr{height:60px;width:60px}
.print-format table.items th, .print-format table.items td { min-width: 0 !important; white-space: normal !important; overflow-wrap: anywhere !important; word-break: break-word !important; }
.print-format table.items .col-photo { text-align: center; white-space: nowrap !important; border-right: 1px solid #ddd; }
.print-format table.items th.col-item { padding-left: 6px !important; }
.print-format table.items .col-qty, .print-format table.items .col-uom, .print-format table.items .col-rate, .print-format table.items .col-amount { white-space: nowrap !important; overflow-wrap: normal !important; word-break: normal !important; }
.print-format table.items tbody td { font-size: calc(var(--solua-font-size) - 1pt); }
.print-format .nowrap { white-space: nowrap !important; }
.print-format table.items th .nowrap, .print-format table.dn-items th .nowrap { color: #607d8b !important; }
.print-format table.items .col-description, .print-format table.items .col-qty, .print-format table.items .col-uom, .print-format table.items .col-rate, .print-format table.items .col-amount { padding-left: 1px !important; padding-right: 1px !important; }
.print-format table.items caption.items-title { caption-side: top; background: #f5f1e9; border-bottom: 1px solid #ddd; padding: 3px 4px; text-align: center; color: #607d8b; white-space: nowrap; }
.print-format table.items thead { display: table-row-group !important; }

.print-format table.items .col-rate { padding-left: 0 !important; padding-right: 0 !important; }
.print-format table.items .col-amount { padding-left: 0 !important; padding-right: 1ch !important; }
.print-format table.items th.col-amount, .print-format table.items td.col-amount { text-align: right !important; }

.print-format table.items th, .print-format table.items td { border: 1px solid #aeb8be !important; }
.print-format table.items .col-spu, .print-format table.items .col-sku, .print-format table.items .col-barcode { white-space: nowrap !important; overflow-wrap: normal !important; word-break: normal !important; overflow: visible !important; text-overflow: clip !important; }
.print-format table.items col.col-qty, .print-format table.items col.col-rate { min-width: 0 !important; }
